{{ assert_case_vars() }}
with business as (select
    CAST(f.tenant_id AS String) AS `tenant_id`,
    CAST(f.opportunity_key AS String) AS `opportunity_key`,
    CAST(f.opportunity_id AS Int64) AS `opportunity_id`,
    CAST(f.company_key AS Nullable(String)) AS `company_key`,
    CAST(f.company_version_key AS Nullable(String)) AS `company_version_key`,
    CAST(f.company_id AS Nullable(Int64)) AS `company_id`,
    CAST(co.company_name AS Nullable(String)) AS `company_name`,
    CAST(f.event_key AS String) AS `event_key`,
    CAST(f.visit_key AS Nullable(String)) AS `visit_key`,
    CAST(f.event_type AS String) AS `event_type`,
    CAST(f.event_at AS Nullable(DateTime64(3, 'UTC'))) AS `event_at`,
    CAST(toDate(f.event_at,'Europe/Paris') AS Nullable(Date)) AS `event_date`,
    CAST(f.event_time_basis AS String) AS `event_time_basis`,
    CAST(f.is_event_time_accepted AS Nullable(Bool)) AS `is_event_time_accepted`,
    CAST(f.from_stage_id AS Nullable(Int64)) AS `from_stage_id`,
    CAST(f.to_stage_id AS Nullable(Int64)) AS `to_stage_id`,
    CAST(f.from_stage_version_key AS Nullable(String)) AS `from_stage_version_key`,
    CAST(f.to_stage_version_key AS Nullable(String)) AS `to_stage_version_key`,
    CAST(fst.stage_label AS Nullable(String)) AS `from_stage_label`,
    CAST(tost.stage_label AS Nullable(String)) AS `to_stage_label`,
    CAST(f.nb_events AS Nullable(UInt8)) AS `nb_events`,
    CAST(f.sum_generated_pipeline_amount AS Nullable(Decimal(38,4))) AS `sum_generated_pipeline_amount`,
    CAST(f.sum_signed_mrr AS Nullable(Decimal(38,4))) AS `sum_signed_mrr`,
    CAST(f.amount_basis AS Nullable(String)) AS `amount_basis`,
    CAST(f.currency_code AS Nullable(String)) AS `currency_code`,
    CAST(false AS Bool) AS `is_generated_amount_calculable`,
    CAST(false AS Bool) AS `is_signed_mrr_calculable`,
    CAST(f.cycle_started_at AS Nullable(DateTime64(3, 'UTC'))) AS `cycle_started_at`,
    CAST(f.completed_cycle_duration_seconds AS Nullable(Float64)) AS `completed_cycle_duration_seconds`,
    CAST(f.completed_cycle_duration_seconds/86400. AS Nullable(Float64)) AS `completed_cycle_duration_days`,
    CAST(f.is_contribution_eligible AS Nullable(Bool)) AS `is_eligible`,
    CAST(f.sale_type_id AS Nullable(Int64)) AS `sale_type_id`,
    CAST(f.sale_type_key AS Nullable(String)) AS `sale_type_key`,
    CAST(f.sale_type_version_key AS Nullable(String)) AS `sale_type_version_key`,
    CAST(ty.sale_type_label AS Nullable(String)) AS `sale_type_label`,
    CAST(f.acquisition_channel_key AS Nullable(String)) AS `channel_key`,
    CAST(f.channel_version_key AS Nullable(String)) AS `channel_version_key`,
    CAST(ch.channel_label AS Nullable(String)) AS `channel_label`,
    CAST(f.channel_candidate_code AS Nullable(String)) AS `channel_candidate_code`,
    CAST(f.is_channel_calculable AS Bool) AS `is_channel_calculable`,
    CAST(f.employee_key AS Nullable(String)) AS `employee_key`,
    CAST(f.employee_version_key AS Nullable(String)) AS `employee_version_key`,
    CAST(em.employee_display_name AS Nullable(String)) AS `employee_display_name`,
    CAST(f.team_key AS Nullable(String)) AS `team_key`,
    CAST(f.team_version_key AS Nullable(String)) AS `team_version_key`,
    CAST(tm.team_name AS Nullable(String)) AS `team_name`,
    CAST(f.is_team_calculable AS Bool) AS `is_team_calculable`,
    CAST(f.calculation_status AS String) AS `calculation_status`,
    CAST(f.status_reason AS Nullable(String)) AS `status_reason`
from {{ ref('fct_opportunity_event') }} f left join {{ ref('dim_company') }} co on f.model_run_id=co.model_run_id and f.company_version_key=co.company_version_key left join {{ ref('dim_stage') }} fst on f.model_run_id=fst.model_run_id and f.from_stage_version_key=fst.stage_version_key left join {{ ref('dim_stage') }} tost on f.model_run_id=tost.model_run_id and f.to_stage_version_key=tost.stage_version_key left join {{ ref('dim_sale_type') }} ty on f.model_run_id=ty.model_run_id and f.sale_type_version_key=ty.sale_type_version_key left join {{ ref('dim_channel') }} ch on f.model_run_id=ch.model_run_id and f.channel_version_key=ch.channel_version_key left join {{ ref('dim_employee') }} em on f.model_run_id=em.model_run_id and f.employee_version_key=em.employee_version_key left join {{ ref('dim_team') }} tm on f.model_run_id=tm.model_run_id and f.team_version_key=tm.team_version_key where f.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }}),
